import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), k = (int) nextLong();
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nextLong();
        int[] p = new int[k];
        for (int i = 0; i < k; i++) p[i] = (int) nextLong();
        Arrays.sort(p);
        // Pair the i-th smallest position with the i-th largest.
        long total = 0;
        for (int i = 0; i < k / 2; i++) total += prefix[p[k - 1 - i] + 1] - prefix[p[i]];
        System.out.println(total % 1000000007L);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := int(nextInt()), int(nextInt())
	prefix := make([]int64, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i] + nextInt()
	}
	p := make([]int, k)
	for i := range p {
		p[i] = int(nextInt())
	}
	slices.Sort(p)
	// Pair the i-th smallest position with the i-th largest.
	total := int64(0)
	for i := 0; i < k/2; i++ {
		total += prefix[p[k-1-i]+1] - prefix[p[i]]
	}
	fmt.Println(total % 1000000007)
}
